const listTrails = `-- name: ListTrails :many
SELECT "partition", account_id, region, name, id, bucket, prefix, include_global, multi_region, recursive_logging, logging, created, modified, started, stopped, stop_after, logs_group_arn, logs_role_arn, kms_key_id, sns_topic_name, organization_id, log_file_validation FROM cloudtrail_trails WHERE partition=? AND account_id=? ORDER BY region, name
`

type ListTrailsParams struct {
	Partition string
	AccountID string
}

func (q *Queries) ListTrails(ctx context.Context, arg ListTrailsParams) ([]CloudtrailTrail, error) {
	rows, err := q.db.QueryContext(ctx, listTrails, arg.Partition, arg.AccountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []CloudtrailTrail{}
	for rows.Next() {
		var i CloudtrailTrail
		if err := rows.Scan(
			&i.Partition,
			&i.AccountID,
			&i.Region,
			&i.Name,
			&i.ID,
			&i.Bucket,
			&i.Prefix,
			&i.IncludeGlobal,
			&i.MultiRegion,
			&i.RecursiveLogging,
			&i.Logging,
			&i.Created,
			&i.Modified,
			&i.Started,
			&i.Stopped,
			&i.StopAfter,
			&i.LogsGroupArn,
			&i.LogsRoleArn,
			&i.KmsKeyID,
			&i.SnsTopicName,
			&i.OrganizationID,
			&i.LogFileValidation,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

